import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"18、【蛊】 巽下艮上","description":"周易口诀义 - 18、【蛊】 巽下艮上","frontmatter":{"title":"18、【蛊】 巽下艮上","description":"周易口诀义 - 18、【蛊】 巽下艮上"},"headers":[],"relativePath":"zh/classics/koujueyi/020.md","filePath":"zh/classics/koujueyi/020.md"}'),r={name:"zh/classics/koujueyi/020.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_18、【蛊】-巽下艮上" tabindex="-1">18、【蛊】 巽下艮上 <a class="header-anchor" href="#_18、【蛊】-巽下艮上" aria-label="Permalink to “18、【蛊】 巽下艮上”">​</a></h1><p>彖曰：「蛊」，刚上而柔下，巽而止，蛊。蛊元亨，而天下治也。「利涉大川」，往有事也。「先甲三日，后甲三日」，终则有始，天行也。</p><p>象曰：山下有风，蛊，君子以振民育德。</p><p>初六：干父之蛊，有子，考无咎，厉终吉。</p><p>象曰：「干父之蛊」，意承考也。</p><p>九二：干母之蛊，不可贞。</p><p>象曰：「干母之蛊」，得中道也。</p><p>九三：干父之蛊，小有悔，无大咎。</p><p>象曰：「干父之蛊」，终无咎也。</p><p>六四，裕父之蛊，往见吝。</p><p>象曰：「裕父之蛊」，往未得也。</p><p>六五，干父之蛊，用誉。</p><p>象曰：「干父用誉」，承以德也。</p><p>上九，不事王侯，高尚其事。</p><p>象曰：「不事王侯」，志可则也。</p><p>解读</p><p>蛊，元亨，利涉大川。「蛊」，事也，谓创制立法有为之事也。教化必大通，故曰「元亨」也；立法施令大行，故曰「利涉大川」也。「先甲三日，后甲三日」者，甲创制之始，故创令立法先三日，恐人未晓，殷勤告示云「后甲三日」。如此再三，丁宁宣布，此后犯者必诛，使民无怨，乃得「无咎」也。象曰「山下有风，蛊」者，先儒云：「蛊，惑也。」按春秋「女惑男，风落山谓之蛊」。既有惑乱，当以教事制之，非是蛊训为「事」，亦犹风行山下，惑乱万物，奸在人间，惑乱众庶，故以教法齐之也。「君子以振民育德」者，君子以振济人民，象风之散布；育养其德，象山之安静也。</p><p>「初六，干父之蛊，有子，考无咎，厉终吉」者，考是父，妣是母，此即先儒通称也。初六处事之初，即能干成父事，故曰「干父之蛊」也；子能干了家事，父又何忧？父能无虑，故曰「有子，考无咎」也。治家之初，恐有危厉，而能干济家事，克终父命，故曰「厉终吉」也。</p><p>「九二，干母之蛊，不可贞」者，以阳居阴，而又处中，女人以内为本，故曰「干母之蛊」也。女人之性情多狠戾，故不可全为正，故云「不可贞」。</p><p>「九三，干父之蛊，小有悔，无大咎」者，以阳居阳，处一家之刚正，能干济父事，故曰「干父之蛊」；为无其应，即不可以行，故「小有悔吝」，能堪家事，即「终无大咎」矣。</p><p>「六四，裕父之蛊，往见吝」者，「裕」，宽也；以阴得位，宽猛得宜，即是能容「裕父之蛊」也。亦是无应而行，人所不亲，故曰「往见吝」也。</p><p>「六五干父之蛊，用誉」者，干事得至尊位，是能干办父事，承先之德，故有美誉于外。孝经云「立身行道，扬名于后世，以显父母」是也。</p><p>「上九：不事王侯，高尚其事」者，最处事上，是能高尚其名，不羁其身，但可清虚守道，不事君侯，众多敬仰，故曰「高尚其事」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
